  val all: List<IsoLanguage> by lazy {
    val raw = DATA_0 + DATA_1 + DATA_2 + DATA_3
    raw.split('\n').mapNotNull { line ->
      if (line.isEmpty()) return@mapNotNull null
      val parts = line.split(':')
      if (parts.size >= 3) {
        IsoLanguage(
          id = parts[0],
          part1 = parts[1],
          name = parts.subList(2, parts.size).joinToString(":"),
        )
      } else {
        null
      }
    }
  }

  private val byCodeMap: Map<String, IsoLanguage> by lazy {
    val map = HashMap<String, IsoLanguage>(all.size * 2)
    for (lang in all) {
      map[lang.id.lowercase()] = lang
      if (lang.part1.isNotEmpty()) {
        map[lang.part1.lowercase()] = lang
      }
    }
    map
  }

  /** Finds a language by its ISO 639-1 (2-letter) or ISO 639-3 (3-letter) code, case-insensitive. */
  fun findByCode(code: String): IsoLanguage? = byCodeMap[code.trim().lowercase()]

  /**
   * Filters languages matching [query] by name, 2-letter code, or 3-letter code.
   * If [query] is blank, returns the first [limit] languages (or common ones first).
   */
  fun search(query: String, limit: Int = 50): List<IsoLanguage> {
    val q = query.trim().lowercase()
    if (q.isEmpty()) return all.take(limit)
    val matches = ArrayList<IsoLanguage>()
    // Exact code match first
    findByCode(q)?.let { matches.add(it) }
    for (lang in all) {
      if (matches.size >= limit) break
      if (matches.contains(lang)) continue
      if (lang.id.lowercase().startsWith(q) ||
        lang.part1.lowercase().startsWith(q) ||
        lang.name.lowercase().contains(q)
      ) {
        matches.add(lang)
      }
    }
    return matches
  }
